# Let me visualize each colored region as it appears in the grid
# and check if they form complete rectangles with holes

def print_region(grid, color, cells):
    rows = [r for r, c in cells]
    cols = [c for r, c in cells]
    min_r, min_c, max_r, max_c = min(rows), min(cols), max(rows), max(cols)

    print(f"Color {color}: bounding box rows {min_r}-{max_r}, cols {min_c}-{max_c}")
    for r in range(min_r, max_r + 1):
        line = []
        for c in range(min_c, max_c + 1):
            if (r, c) in cells:
                line.append(f'#{color}')
            else:
                line.append('.')
        print(f"  {line}")

for color in [3, 5, 6, 8]:
    print(f"\n=== Region {color} ===")
    region = None
    for r in grid:
        if color in r:
            region = [(i, j) for i, row in enumerate(grid) for j, val in enumerate(row) if val == color]
    print_region(grid, color, region)

